package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestPrintExpectedIdsAndUris(t *testing.T) {
	cwd, _ := os.Getwd()
	oldRoot := rootDir
	rootDir = findTestRepoRoot(cwd)
	defer func() { rootDir = oldRoot }()

	files := []string{
		"semio/assets/repo/some/folder/file_fixed.tsx",
		"semio/assets/repo/some/folder/file_fixed.go",
		"semio/assets/repo/some/folder/file_fixed.py",
		"semio/assets/repo/some/folder/file_fixed.cs",
		"semio/assets/repo/some/folder/file_fixable.tsx",
	}

	type SectionDef struct {
		Section    string
		DefName    string
		DefKind    DefinitionKind
	}

	fileSections := map[string][]SectionDef{
		"semio/assets/repo/some/folder/file_fixed.tsx": {
			{"Types", "FixedType", DefinitionKindInterface},
			{"Types", "FixedKind", DefinitionKindInterface},
			{"Components", "FixedComponent", DefinitionKindImplementation},
		},
		"semio/assets/repo/some/folder/file_fixed.go": {
			{"Functions", "FixedValue", DefinitionKindImplementation},
		},
		"semio/assets/repo/some/folder/file_fixed.py": {
			{"Functions", "fixed_function", DefinitionKindImplementation},
		},
		"semio/assets/repo/some/folder/file_fixed.cs": {
			{"Classes", "FixedClass", DefinitionKindInterface},
		},
		"semio/assets/repo/some/folder/file_fixable.tsx": {
			{"MissingEnd", "missingEnd", DefinitionKindConstant},
			{"Alpha", "mismatchName", DefinitionKindConstant},
		},
	}

	_ = filepath.Join
	_ = strings.TrimSpace

	for _, f := range files {
		fmt.Printf("=== %s ===\n", f)
		fmt.Printf("FileHeaderId: %s\n", FileHeaderId(f))
		fmt.Printf("FileHeaderUri: %s\n", FileHeaderUri(f))

		if defs, ok := fileSections[f]; ok {
			for _, d := range defs {
				fmt.Printf("SectionHeaderId(%s): %s\n", d.Section, SectionHeaderId(f, d.Section))
				fmt.Printf("SectionHeaderUri(%s): %s\n", d.Section, SectionHeaderUri(f, d.Section))
				fmt.Printf("DefinitionHeaderId(%s/%s): %s\n", d.Section, d.DefName, DefinitionHeaderId(f, d.Section, d.DefName, d.DefKind))
				fmt.Printf("DefinitionHeaderUri(%s/%s): %s\n", d.Section, d.DefName, DefinitionHeaderUri(f, d.Section, d.DefName))
			}
		}
		fmt.Println()
	}
}
GOEOF
cp /tmp/print_ids_test.go print_ids_test.go && go test -run TestPrintExpectedIdsAndUris -v -count=1 -timeout 30s 2>&1 | grep -E "^(===|File|Section|Definition|---)" | head -60

